import{_ as a,a0 as l,w as i,s,ao as u,I as e,x as p,a1 as o,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"使用 utmpdump 监控 CentOS 用户登录历史 | LCTT x X-CMD","titleTemplate":false,"description":"使用 utmpdump 监控 CentOS 用户登录历史 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 utmpdump 监控 CentOS 用户登录历史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 utmpdump 监控 CentOS 用户登录历史 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140926 How to monitor user login history on CentOS with utmpdump","title":"使用 utmpdump 监控 CentOS 用户登录历史","tag":"201411","desc":""},"relativePath":"201411/20140926 How to monitor user login history on CentOS with utmpdump.md","filePath":"[post].md"}'),n={name:"201411/20140926 How to monitor user login history on CentOS with utmpdump.md"};function d(g,t,c,f,T,_){const m=l("Link");return i(),s("div",null,[t[16]||(t[16]=u(`<h1 id="使用-utmpdump-监控-centos-用户登录历史" tabindex="-1">使用 utmpdump 监控 CentOS 用户登录历史 <a class="header-anchor" href="#使用-utmpdump-监控-centos-用户登录历史" aria-label="Permalink to “使用 utmpdump 监控 CentOS 用户登录历史”">​</a></h1><p>保留、维护和分析日志（如某个特定时期内发生过的，或正在发生的帐号事件），是Linux系统管理员最基础和最重要的任务之一。对于用户管理，检查用户的登入和登出日志（不管是失败的，还是成功的）可以让我们对任何潜在的安全隐患或未经授权使用系统的情况保持警惕。例如，工作时间之外或放假期间的来自未知IP地址或帐号的远程登录应当发出红色警报。</p><p>在CentOS系统上，用户登录历史存储在以下这些文件中：</p><ul><li>/var/run/utmp（用于记录当前打开的会话）被who和w工具用来记录当前有谁登录以及他们正在做什么，而uptime用来记录系统启动时间。</li><li>/var/log/wtmp （用于存储系统连接历史记录）被last工具用来记录最后登录的用户的列表。</li><li>/var/log/btmp（记录失败的登录尝试）被lastb工具用来记录最后失败的登录尝试的列表。</li></ul><p><img src="https://farm4.staticflickr.com/3871/15106743340_bd13fcfe1c_o.png" alt=""></p><p>在本文中，我将介绍如何使用utmpdump，这个小程序来自sysvinit-tools包，可以用于转储二进制日志文件到文本格式的文件以便检查。此工具默认在CentOS 6和7系列上可用。utmpdump收集到的信息比先前提到过的工具的输出要更全面，这让它成为一个胜任该工作的很不错的工具。除此之外，utmpdump可以用于修改utmp或wtmp。如果你想要修复二进制日志中的任何损坏条目，它会很有用（LCTT 译注：我怎么觉得这像是做坏事的前奏？）。</p><h3 id="utmpdump的使用及其输出说明" tabindex="-1">Utmpdump的使用及其输出说明 <a class="header-anchor" href="#utmpdump的使用及其输出说明" aria-label="Permalink to “Utmpdump的使用及其输出说明”">​</a></h3><p>正如我们之前提到的，这些日志文件，与我们大多数人熟悉的其它日志相比（如/var/log/messages，/var/log/cron，/var/log/maillog），是以二进制格式存储的，因而我们不能使用像less或more这样的文件命令来查看它们的内容。所以，utmpdump的出现拯救了世界。</p><p>为了要显示/var/run/utmp的内容，请运行以下命令：</p><pre><code># utmpdump /var/run/utmp 
</code></pre><p><img src="https://farm6.staticflickr.com/5595/15106696599_60134e3488_z.jpg" alt=""></p><p>同样要显示/var/log/wtmp的内容：</p><pre><code># utmpdump /var/log/wtmp 
</code></pre><p><img src="https://farm6.staticflickr.com/5591/15106868718_6321c6ff11_z.jpg" alt=""></p><p>最后，对于/var/log/btmp：</p><pre><code># utmpdump /var/log/btmp 
</code></pre><p><img src="https://farm6.staticflickr.com/5562/15293066352_c40bc98ca4_z.jpg" alt=""></p><p>正如你所能看到的，三种情况下的输出结果是一样的，除了utmp和btmp的记录是按时间排序，而wtmp的顺序是颠倒的这个原因外（LCTT 译注：此处原文有误，实际上都是按照时间顺序排列的）。</p><p>每个日志行格式化成了多列，说明如下。第一个字段显示了会话识别符，而第二个字段则是PID。第三个字段可以是以下值：--（表示运行等级改变或系统重启），bw（启动守候进程），数字（表示TTY编号），或者字符和数字（表示伪终端）。第四个字段可以为空或用户名、重启或运行级别。第五个字段是主TTY或PTY（伪终端），如果此信息可获得的话。第六个字段是远程主机名（如果是本地登录，该字段为空，运行级别信息除外，它会返回内核版本）。第七个字段是远程系统的IP地址（如果是本地登录，该字段为0.0.0.0）。如果没有提供DNS解析，第六和第七字段会显示相同的信息（远程系统的IP地址）。最后一个（第八）字段指明了该记录创建的日期和时间。</p><h3 id="utmpdump使用样例" tabindex="-1">Utmpdump使用样例 <a class="header-anchor" href="#utmpdump使用样例" aria-label="Permalink to “Utmpdump使用样例”">​</a></h3><p>下面提供了一些utmpdump的简单使用情况。</p><p>1、 检查8月18日到9月17日之间某个特定用户（如gacanepa）的登录次数。</p><pre><code># utmpdump /var/log/wtmp | grep gacanepa 
</code></pre><p><img src="https://farm4.staticflickr.com/3857/15293066362_fb2dd566df_z.jpg" alt=""></p>`,24)),e("p",null,[t[1]||(t[1]=p("如果你需要回顾先前日期的登录信息，你可以检查/var/log下的wtmp-YYYYMMDD（或wtmp.[1...N]）和btmp-YYYYMMDD（或btmp.[1...N]）文件，这些是由",-1)),o(m,{href:"http://linux.cn/article-4126-1.html"},{default:r(()=>[...t[0]||(t[0]=[p("logrotate",-1)])]),_:1}),t[2]||(t[2]=p("生成的旧wtmp和btmp的归档文件。",-1))]),t[17]||(t[17]=u(`<p>2、 统计来自IP地址192.168.0.101的登录次数。</p><pre><code># utmpdump /var/log/wtmp | grep 192.168.0.101 
</code></pre><p><img src="https://farm4.staticflickr.com/3842/15106743480_55ce84c9fd_z.jpg" alt=""></p><p>3、 显示失败的登录尝试。</p><pre><code># utmpdump /var/log/btmp 
</code></pre><p><img src="https://farm4.staticflickr.com/3858/15293065292_e1d2562206_z.jpg" alt=""></p><p>在/var/log/btmp输出中，每个日志行都与一个失败的登录尝试相关（如使用不正确的密码，或者一个不存在的用户ID）。上面图片中高亮部分显示了使用不存在的用户ID登录，这警告你有人尝试猜测常用帐号名来闯入系统。这在使用tty1的情况下是个极其严重的问题，因为这意味着某人对你机器上的终端具有访问权限（该检查一下谁拿到了进入你数据中心的钥匙了，也许吧？）</p><p>4、 显示每个用户会话的登入和登出信息</p><pre><code># utmpdump /var/log/wtmp 
</code></pre><p><img src="https://farm4.staticflickr.com/3835/15293065312_c762360791_z.jpg" alt=""></p><p>在/var/logwtmp中，一次新的登录事件的特征是，第一个字段为‘7’，第三个字段是一个终端编号（或伪终端id），第四个字段为用户名。相关的登出事件会在第一个字段显示‘8’，第二个字段显示与登录一样的PID，而终端编号字段空白。例如，仔细观察上面图片中PID 1463的行。</p><ul><li>在 [Fri Sep 19 11:57:40 2014 ART]，TTY1上显示登录提示符。</li><li>在 [Fri Sep 19 12:04:21 2014 ART]，用户 root 登入。</li><li>在 [Fri Sep 19 12:07:24 2014 ART]，用户 root 登出。</li></ul><p>旁注：第四个字段的LOGIN意味着出现了一次登录到第五字段指定的终端的提示。</p><p>到目前为止，我介绍一些有点琐碎的例子。你可以将utmpdump和其它一些文本处理工具，如awk、sed、grep或cut组合，来产生过滤和加强的输出。</p><p>例如，你可以使用以下命令来列出某个特定用户（如gacanepa）的所有登录事件，并发送输出结果到.csv文件，它可以用像LibreOffice Calc或Microsoft Excel之类的文字或工作簿应用程序打开查看。让我们只显示PID、用户名、IP地址和时间戳：</p><pre><code> # utmpdump /var/log/wtmp | grep -E &quot;\\[7].*gacanepa&quot; | awk -v OFS=&quot;,&quot; &#39;BEGIN {FS=&quot;] &quot;}; {print $2,$4,$7,$8}&#39; | sed -e &#39;s/\\[//g&#39; -e &#39;s/\\]//g&#39; 
</code></pre><p><img src="https://farm4.staticflickr.com/3851/15293065352_91e1c1e4b6_z.jpg" alt=""></p><p>就像上面图片中三个高亮区域描绘的那样，过滤逻辑操作是由三个管道步骤组成的。第一步用于查找由用户gacanepa触发的登录事件（[7]）；第二步和第三部用于选择期望的字段，移除utmpdump输出的方括号并设置输出字段分隔符为逗号。</p><p>当然，如果你想要在以后打开来看，你需要重定向上面的命令输出到文件（添加“&gt;[文件名].csv”到命令后面）。</p><p><img src="https://farm4.staticflickr.com/3889/15106867768_0e37881a25_z.jpg" alt=""></p><p>在更为复杂的例子中，如果你想要知道在特定时间内哪些用户（在/etc/passwd中列出）没有登录，你可以从/etc/passwd中提取用户名，然后运行grep命令来获取/var/log/wtmp输出中对应用户的列表。就像你看到的那样，有着无限可能。</p><p>在进行总结之前，让我们简要地展示一下utmpdump的另外一种使用情况：修改utmp或wtmp。由于这些都是二进制日志文件，你不能像编辑文件一样来编辑它们。取而代之是，你可以将其内容输出成为文本格式，并修改文本输出内容，然后将修改后的内容导入回二进制日志中。如下：</p><pre><code># utmpdump /var/log/utmp &gt; tmp_output
&lt;使用文本编辑器修改 tmp_output&gt;
# utmpdump -r tmp_output &gt; /var/log/utmp 
</code></pre><p>这在你想要移除或修复二进制日志中的任何伪造条目时很有用。</p><p>下面小结一下，utmpdump从utmp、wtmp和btmp日志文件或轮循的旧归档文件来读取详细的登录事件，来补充如who，w，uptime，last，lastb之类的标准工具的不足，这也使得它成为一个很棒的工具。</p><p>你可以随意添加评论以加强本帖的含金量。</p><hr>`,27)),e("p",null,[t[4]||(t[4]=p("via: ",-1)),o(m,{href:"http://xmodulo.com/2014/09/monitor-user-login-history-centos-utmpdump.html"},{default:r(()=>[...t[3]||(t[3]=[p("http://xmodulo.com/2014/09/monitor-user-login-history-centos-utmpdump.html",-1)])]),_:1})]),e("p",null,[t[8]||(t[8]=p("作者：",-1)),o(m,{href:"http://xmodulo.com/author/gabriel"},{default:r(()=>[...t[5]||(t[5]=[p("Gabriel Cánepa",-1)])]),_:1}),t[9]||(t[9]=p(" 译者：",-1)),o(m,{href:"https://github.com/GOLinux"},{default:r(()=>[...t[6]||(t[6]=[p("GOLinux",-1)])]),_:1}),t[10]||(t[10]=p(" 校对：",-1)),o(m,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[p("wxy",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=p("本文由 ",-1)),o(m,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[p("LCTT",-1)])]),_:1}),t[14]||(t[14]=p(" 原创翻译，",-1)),o(m,{href:"http://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[p("Linux中国",-1)])]),_:1}),t[15]||(t[15]=p(" 荣誉推出",-1))])])}const h=a(n,[["render",d]]);export{v as __pageData,h as default};
